theorem genLoopMap_homotopic (f : C(X, Y)) (hf : f x = y) {p q : Ω^ N X x}
    (h : GenLoop.Homotopic p q) :
    GenLoop.Homotopic (genLoopMap f hf p) (genLoopMap f hf q)

theorem genLoop_homotopic_of_dist_lt_two {N : Type*} {x : UnitSphere E}
    (p q : Ω^ N (UnitSphere E) x) (h : ∀ t, dist (p t) (q t) < 2) :
    GenLoop.Homotopic p q

theorem chart_deriv_inj {D : (Fin (n + 1) → ℝ) →L[ℝ] ℝ} {s : Fin (n + 1)}
    (hd : D (Pi.single s 1) ≠ 0) (ξ : Fin (n + 1) → ℝ)
    (hξ : ξ + (D ξ - ξ s) • Pi.single s 1 = 0) : ξ = 0

theorem fderiv_eq_zero_of_mem_vanishSet {U : Set (Fin p → ℝ)}
    {f : (Fin p → ℝ) → Fin q → ℝ} {i : ℕ} (hi : 1 ≤ i) {x : Fin p → ℝ}
    (hx : x ∈ vanishSet U f i) : fderiv ℝ f x = 0

theorem isClosed_setOf_not_surjective {E : Type*} [NormedAddCommGroup E]
    [NormedSpace ℝ E] {q : ℕ} :
    IsClosed {L : E →L[ℝ] (Fin q → ℝ) | ¬Surjective L}

theorem isOpen_setOf_surjective {E : Type*} [NormedAddCommGroup E]
    [NormedSpace ℝ E] {q : ℕ} :
    IsOpen {L : E →L[ℝ] (Fin q → ℝ) | Surjective L}

theorem vanishSet_subset_critSet {U : Set (Fin p → ℝ)}
    {f : (Fin p → ℝ) → Fin (q + 1) → ℝ} {i : ℕ} (hi : 1 ≤ i) :
    vanishSet U f i ⊆ critSet U f

theorem exists_grid_index {ρ : ℝ} (hρ : 0 < ρ) {m : ℕ} (hm : 0 < m) {u : ℝ}
    (h0 : 0 ≤ u) (h2 : u ≤ 2 * ρ) :
    ∃ j : ℕ, j < m ∧ |u - (2 * j + 1) * ρ / m| ≤ ρ / m

theorem grid_subset_closedBall {x₀ : Fin p → ℝ} {ρ : ℝ} (hρ : 0 < ρ) {m : ℕ}
    (hm : 0 < m) (v : Fin p → Fin m) :
    closedBall (gridCenter x₀ ρ m v) (ρ / m) ⊆ closedBall x₀ ρ

theorem euclidean_null_of_pi_null {A : Set (EuclideanSpace ℝ (Fin q))}
    {B : Set (Fin q → ℝ)} (hAB : ∀ a ∈ A, WithLp.ofLp a ∈ B)
    (hB : volume B = 0) : volume A = 0

theorem sard_dense_regular_values
    {f : EuclideanSpace ℝ (Fin p) → EuclideanSpace ℝ (Fin q)}
    (hf : ContDiff ℝ ∞ f) : Dense {y | IsRegularValue f y}

theorem sard_dense_regular_values_on
    {U : Set (EuclideanSpace ℝ (Fin p))} (hU : IsOpen U)
    {f : EuclideanSpace ℝ (Fin p) → EuclideanSpace ℝ (Fin q)}
    (hf : ContDiffOn ℝ ∞ f U) : Dense {y | IsRegularValueOn f U y}

theorem sard_global {f : EuclideanSpace ℝ (Fin p) → EuclideanSpace ℝ (Fin q)}
    (hf : ContDiff ℝ ∞ f) :
    volume (f '' {x | ¬Function.Surjective (fderiv ℝ f x)}) = 0

theorem sard_of_lt (hpq : p < q)
    {f : EuclideanSpace ℝ (Fin p) → EuclideanSpace ℝ (Fin q)}
    (hf : ContDiff ℝ 1 f) : volume (Set.range f) = 0

theorem collared_eq_basepoint (p : Ω^ N X x) {t : I^N}
    (h : ∃ i, (t i : ℝ) ≤ 1 / 4 ∨ 3 / 4 ≤ (t i : ℝ)) :
    collared p t = x

lemma inverseTrack_of_three_quarter_le (x : E) {t : ℝ}
    (ht : 3 / 4 ≤ t) :
    A.inverseTrack (spaceTime x t) = A.inverse 1 x

@[simp] theorem pullbackSign_apply {X : FramedLevelSet n}
    (S : FiberSign X) (x : E) :
    A.pullbackSign S x = S (A.inverse 1 x)

theorem FixedOn.inverseTrack_eq {A : SmoothAmbientIsotopy n} {K : Set E}
    (hA : A.FixedOn K) {v : EuclideanSpace ℝ (Fin (n + 1 + 1))}
    (hv : initCLM (n + 1) v ∈ K) :
    A.inverseTrack v = initCLM (n + 1) v

theorem FixedOn.inverse_eq {A : SmoothAmbientIsotopy n} {K : Set E}
    (hA : A.FixedOn K) {s : ℝ} (hs : s ∈ Icc (0 : ℝ) 1)
    {x : E} (hx : x ∈ K) : A.inverse s x = x

theorem FixedOn.pullback_g_eq {A : SmoothAmbientIsotopy n} {K : Set E}
    (hA : A.FixedOn K) (X : FramedLevelSet n) {x : E} (hx : x ∈ K) :
    (A.pullback X).g x = X.g x

theorem FixedOn.conjugateAffine {A : SmoothAmbientIsotopy n} {K : Set E}
    (hA : A.FixedOn K) (L : E ≃L[ℝ] E) (b : E) :
    (A.conjugateAffine L b).FixedOn
      {x | L.symm (x - b) ∈ K}

theorem FixedOn.conjugateByEndpoint {B A : SmoothAmbientIsotopy n}
    {K : Set E} (hB : B.FixedOn K) :
    (B.conjugateByEndpoint A).FixedOn (A.forward 1 '' K)

theorem solution_mem_fiber {γ : ℝ → EuclideanSpace ℝ (Fin (n + 1))}
    (hγ : ∀ t, HasDerivAt γ (V.v (γ t)) t) (h0 : γ 0 ∈ X.fiber) :
    ∀ t, γ t ∈ X.fiber

lemma linearIndependent_frameAt (X : FramedLevelSet n) {x : E}
    (hx : x ∈ regularSet X.g) :
    LinearIndependent ℝ (frameAt X x)

theorem solution_mem_fiber {γ : ℝ → EuclideanSpace ℝ (Fin (n + 2))}
    (hγ : ∀ t, HasDerivAt γ (W.w (γ t)) t) (h0 : γ 0 ∈ C.fiber) :
    ∀ t, γ t ∈ C.fiber

theorem continuous_reflMatrix_comp {α : Type*} [TopologicalSpace α] {g : α → Fin n → ℝ}
    (hg : Continuous g) (hne : ∀ a, g a ⬝ᵥ g a ≠ 0) :
    Continuous fun a => reflMatrix (g a)

theorem rotTo_coe {x y : UnitSphere (EuclideanSpace ℝ (Fin n))}
    (h : -1 < coords x ⬝ᵥ coords y) :
    (rotTo x y : Matrix (Fin n) (Fin n) ℝ) = rotToAux (coords x) (coords y)

theorem rotTo_mulVec {x y : UnitSphere (EuclideanSpace ℝ (Fin n))}
    (h : -1 < coords x ⬝ᵥ coords y) :
    (rotTo x y : Matrix (Fin n) (Fin n) ℝ) *ᵥ coords x = coords y

@[simp] theorem rowsMatrix_matrixRows {m : ℕ}
    (M : Matrix (Fin m) (Fin m) ℝ) :
    rowsMatrix (matrixRows M) = M

theorem det_gsInterp_pos {v : Fin k → EuclideanSpace ℝ (Fin k)}
    (hv : LinearIndependent ℝ v) {s : ℝ} (hs0 : 0 ≤ s) (hs1 : s ≤ 1) :
    0 < (gsInterp v s).det

theorem dotProduct_vecMul_of_mul_transpose {Q : Matrix (Fin k) (Fin k) ℝ}
    (hQ : Q * Qᵀ = 1) (x y : Fin k → ℝ) :
    (x ᵥ* Q) ⬝ᵥ (y ᵥ* Q) = x ⬝ᵥ y

theorem gsInterp_diag {v : Fin k → EuclideanSpace ℝ (Fin k)}
    (hv : LinearIndependent ℝ v) (s : ℝ) (i : Fin k) :
    gsInterp v s i i = (1 - s) * ‖gramSchmidt ℝ v i‖ + s

theorem gsLower_diag {v : Fin k → EuclideanSpace ℝ (Fin k)}
    (hv : LinearIndependent ℝ v) (i : Fin k) :
    gsLower v i i = ‖gramSchmidt ℝ v i‖

theorem inner_eq_zero_of_mem_span_gramSchmidt_Iio
    {v : Fin k → EuclideanSpace ℝ (Fin k)} {j : Fin k}
    {w : EuclideanSpace ℝ (Fin k)}
    (hw : w ∈ Submodule.span ℝ (gramSchmidt ℝ v '' Set.Iio j)) :
    ⟪w, gramSchmidt ℝ v j⟫ = 0

@[simp] theorem rowVecIsometry_apply {Q : Matrix (Fin k) (Fin k) ℝ}
    (hQ : Q * Qᵀ = 1) (x : EuclideanSpace ℝ (Fin k)) :
    rowVecIsometry hQ x = WithLp.toLp 2 ((WithLp.ofLp x) ᵥ* Q)

theorem rowsMatrix_eq_gsLower_mul {v : Fin k → EuclideanSpace ℝ (Fin k)}
    (hv : LinearIndependent ℝ v) :
    rowsMatrix v = gsLower v * rowsMatrix (gramSchmidtNormed ℝ v)

theorem fixedOn_of_field_eq_zero {K : Set E}
    (hzero : ∀ x ∈ K, D.field x = 0) :
    D.toSmoothAmbientIsotopy.FixedOn K

theorem ambientField_eq_zero_of_supportCore_subset {U : Set E}
    (hcore : D.supportCore ⊆ U) {x : E} (hx : x ∉ U) :
    D.ambientField x = 0

theorem bijective_of_det_clmMatrix_ne_zero
    {Φ : EuclideanSpace ℝ (Fin k) →L[ℝ] EuclideanSpace ℝ (Fin k)}
    (h : (clmMatrix Φ).det ≠ 0) : Function.Bijective Φ

theorem mem_specialOrthogonalGroup_transpose {Q : Matrix (Fin k) (Fin k) ℝ}
    (hQ : Q ∈ Matrix.specialOrthogonalGroup (Fin k) ℝ) :
    Qᵀ ∈ Matrix.specialOrthogonalGroup (Fin k) ℝ

theorem FixedOn.signedCobordism_productOn {X₀ X₁ : FramedLevelSet n}
    {D : DefiningMapHomotopy X₀ X₁} {K : Set E} {g : E → F}
    (hD : D.FixedOn K g) (S : FiberSign X₀) :
    (D.signedCobordism S).ProductOn K g S

theorem ProductOn.trans {C₁ C₂ : FramedLevelCobordism n} {K : Set E}
    {g : E → F} (h₁ : C₁.ProductOn K g) (h₂ : C₂.ProductOn K g)
    (hmid : C₁.X₁ = C₂.X₀) : (C₁.trans C₂ hmid).ProductOn K g

theorem ProductOn.trans {X₀ X₁ X₂ : FramedLevelSet n}
    {S₀ : FiberSign X₀} {S₁ : FiberSign X₁} {S₂ : FiberSign X₂}
    {C₁ : SignedFramedLevelCobordism S₀ S₁}
    {C₂ : SignedFramedLevelCobordism S₁ S₂}
    {K : Set E} {g : E → F} {σ : E → ℝ}
    (h₁ : C₁.ProductOn K g σ) (h₂ : C₂.ProductOn K g σ) :
    (SignedFramedLevelCobordism.trans C₁ C₂).ProductOn K g σ

theorem FixedOn.signedCobordism_productOn {A : SmoothAmbientIsotopy n}
    {K : Set E} (hA : A.FixedOn K) {X : FramedLevelSet n}
    (S : FiberSign X) :
    (A.signedCobordism S).ProductOn K X.g S

@[simp] theorem euclideanToMatrix_matrixToEuclidean {m : ℕ}
    (M : Matrix (Fin m) (Fin m) ℝ) :
    euclideanToMatrix (matrixToEuclidean M) = M

theorem matrixGramSchmidtSO_congr {m : ℕ}
    {M N : Matrix (Fin m) (Fin m) ℝ}
    (hMN : M = N) (hM : 0 < M.det) (hN : 0 < N.det) :
    matrixGramSchmidtSO M hM = matrixGramSchmidtSO N hN

@[simp] theorem matrixToEuclidean_euclideanToMatrix {m : ℕ}
    (v : EuclideanSpace ℝ (Fin m × Fin m)) :
    matrixToEuclidean (euclideanToMatrix v) = v

lemma cubeToTubeAmbient_boundary_abs {t : I^(Fin (m + 3))}
    {j : Fin (m + 3)} (hj : t j = 0 ∨ t j = 1) :
    |cubeToTubeAmbient (m := m) t j| = 3

lemma cassiniQ_eq_height_of_eventMap_eq_zero {v : E'}
    (hv : eventMap m v = 0) :
    cassiniQ m (initCLM (m + 3) v) = height (vertC v) / 2

lemma transverse_eq_zero_of_eventMap_eq_zero {v : E'}
    (hv : eventMap m v = 0) (j : Fin (m + 1)) :
    v j.castSucc.castSucc.castSucc = 0

theorem isUnit_gram (X : FramedLevelSet n)
    {x : EuclideanSpace ℝ (Fin (n + 1))}
    (hx : Function.Surjective (fderiv ℝ X.g x)) : IsUnit (gram X x)

theorem isUnit_of_det_clmMatrix_ne_zero
    {A : EuclideanSpace ℝ (Fin k) →L[ℝ] EuclideanSpace ℝ (Fin k)}
    (h : (PolarDecompositionCLM.clmMatrix A).det ≠ 0) : IsUnit A

theorem isUnit_of_injective
    {A : EuclideanSpace ℝ (Fin k) →L[ℝ] EuclideanSpace ℝ (Fin k)}
    (h : Function.Injective A) : IsUnit A
